{
  "findings": [
    {
      "check_id": "CKV2_AWS_6",
      "title": "S3 bucket lacks a Public Access Block",
      "resource": "aws_s3_bucket.cloudtrail_logs",
      "severity": "MEDIUM",
      "explanation": "The CloudTrail log bucket has no account-level bucket guardrail preventing public ACLs or policies. Accidental public exposure could disclose sensitive audit logs."
    },
    {
      "check_id": "CKV_AWS_21",
      "title": "S3 bucket versioning is disabled",
      "resource": "aws_s3_bucket.cloudtrail_logs",
      "severity": "HIGH",
      "explanation": "Without versioning, CloudTrail log objects can be permanently overwritten or deleted. Enabling versioning improves audit-log integrity and recoverability."
    },
    {
      "check_id": "CKV2_AWS_61",
      "title": "S3 bucket lacks a lifecycle configuration",
      "resource": "aws_s3_bucket.cloudtrail_logs",
      "severity": "MEDIUM",
      "explanation": "The bucket has no lifecycle policy for managing accumulated CloudTrail logs. A non-destructive transition policy reduces long-term storage cost while retaining the logs."
    },
    {
      "check_id": "CKV_AWS_145",
      "title": "S3 bucket does not use KMS default encryption",
      "resource": "aws_s3_bucket.cloudtrail_logs",
      "severity": "MEDIUM",
      "explanation": "The bucket does not explicitly configure KMS-backed default encryption for sensitive CloudTrail records. Objects are now encrypted by default using the AWS-managed S3 KMS key."
    },
    {
      "check_id": "CKV_AWS_70",
      "title": "S3 bucket does not enforce encrypted transport",
      "resource": "aws_s3_bucket.cloudtrail_logs",
      "severity": "MEDIUM",
      "explanation": "No bucket policy denies requests made without TLS. This permits clients with otherwise valid permissions to attempt unencrypted access to audit logs."
    }
  ],
  "patched_code": "resource "aws_s3_bucket" "cloudtrail_logs" {
  bucket = "fleet-management-gps-tracking-system-cloudtrail-${random_string.bucket_suffix.result}"
}

resource "aws_s3_bucket_public_access_block" "cloudtrail_logs" {
  bucket = aws_s3_bucket.cloudtrail_logs.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_versioning" "cloudtrail_logs" {
  bucket = aws_s3_bucket.cloudtrail_logs.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "cloudtrail_logs" {
  bucket = aws_s3_bucket.cloudtrail_logs.id

  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = "alias/aws/s3"
      sse_algorithm     = "aws:kms"
    }
  }
}

resource "aws_s3_bucket_lifecycle_configuration" "cloudtrail_logs" {
  bucket = aws_s3_bucket.cloudtrail_logs.id

  rule {
    id     = "transition-cloudtrail-logs"
    status = "Enabled"

    transition {
      days          = 90
      storage_class = "STANDARD_IA"
    }
  }
}

resource "aws_s3_bucket_policy" "cloudtrail_logs" {
  bucket = aws_s3_bucket.cloudtrail_logs.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "DenyInsecureTransport"
        Effect    = "Deny"
        Principal = "*"
        Action    = "s3:*"
        Resource = [
          aws_s3_bucket.cloudtrail_logs.arn,
          "${aws_s3_bucket.cloudtrail_logs.arn}/*"
        ]
        Condition = {
          Bool = {
            "aws:SecureTransport" = "false"
          }
        }
      }
    ]
  })
}
",
  "fix_summary": "Added an S3 Public Access Block, versioning, KMS-backed default encryption, a non-destructive lifecycle transition, and a bucket policy requiring TLS. Event notifications, access logging, and cross-region replication were not added because they require workload-specific destinations or resilience requirements not established by this file."
}
